<script setup lang="ts">import{ref}from"vue";import type{ReviewRecord}from"@/domain/diary/records";defineProps<{review:ReviewRecord}>();const emit=defineEmits<{edit:[ReviewRecord]}>();const reveal=ref(false);</script><template><article class="review-card"><header><div><p class="eyebrow">{{review.estado_publicacao||'Rascunho'}}</p><h3>{{review.titulo_review||review.expand?.titulo?.titulo||'Avaliação sem título'}}</h3></div><strong v-if="review.rating!==undefined">{{review.rating}} / 10</strong></header><p v-if="review.tem_spoilers&&!reveal" class="form-alert">Esta avaliação contém spoilers. <button class="button button-secondary" type="button" @click="reveal=true">Mostrar texto</button></p><p v-else class="review-text">{{review.texto||'Sem texto.'}}</p><footer><span v-if="review.recomenda">Recomendado</span><span v-if="review.favorito">★ Favorita</span><button class="button button-secondary" type="button" @click="emit('edit',review)">Editar</button></footer></article></template>
